-- D17 L3: 与 A001 相交且正常或告警的设备分别缓冲 300 米，合并后裁剪到 A001。复用该覆盖几何，分别计算覆盖面积（平方米）和其中全部燃气管线的总长度（米），保留非空零长度接触记录。
-- 独立只读基准；EPSG:3857、quad_segs=8；不调用工具或执行器。
-- 覆盖几何只生成一次；长度对各源管线相加，不把缓冲面积相加当覆盖面积。
WITH a AS (SELECT geom FROM gis_lab.construction_areas WHERE code='A001'), selected AS (SELECT d.geom FROM gis_lab.gas_devices d CROSS JOIN a WHERE d.status IN ('正常','告警') AND ST_Intersects(d.geom,a.geom)), buffered AS (SELECT ST_Buffer(geom,300,'quad_segs=8') AS geom FROM selected), merged AS (SELECT ST_UnaryUnion(ST_Collect(geom)) AS geom FROM buffered), covered AS (SELECT ST_Intersection(m.geom,a.geom) AS geom FROM merged m CROSS JOIN a), cut AS (SELECT ST_Intersection(g.geom,c.geom) AS geom FROM gis_lab.gas_pipelines g CROSS JOIN covered c WHERE ST_Intersects(g.geom,c.geom)), retained AS (SELECT geom FROM cut WHERE NOT ST_IsEmpty(geom)) SELECT jsonb_build_object('area',(SELECT jsonb_build_object('value',ST_Area(geom),'unit','square_meter','measure','area','measure_srid',3857,'is_empty',ST_IsEmpty(geom)) FROM covered),'gas_length',(SELECT jsonb_build_object('value',COALESCE(sum(ST_Length(geom)),0),'unit','meter','measure','length','measure_srid',3857,'feature_count',count(*)) FROM retained)) AS answer;
